insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-pe-257","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Second-period elements lack vacant d orbitals, so they cannot","options":["form any covalent bond","expand their octet the way heavier congeners can","show a +1 oxidation state","exist as isolated atoms"],"answer_index":1,"explanation":"N, O and F are limited to an octet; P, S and Cl can use 3d orbitals in PF₅, SF₆, ClF₃, and so on.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-258","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lithium differs from the rest of the alkali metals in several properties, including the low solubility of its","options":["chloride only","fluoride and carbonate","all nitrates","hydride vapour"],"answer_index":1,"explanation":"LiF and Li₂CO₃ resemble the corresponding magnesium salts more than those of Na or K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-259","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lithium shows a diagonal relationship with","options":["sodium","magnesium","caesium","fluorine"],"answer_index":1,"explanation":"The Li–Mg pair is the textbook diagonal relationship of group 1 / group 2.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-260","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Beryllium and aluminium form a well-known","options":["inert-pair pair","diagonal pair","isotope pair","noble-gas pair"],"answer_index":1,"explanation":"Be and Al share amphoteric oxides, covalent chlorides and a similar charge-to-radius ratio.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-261","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Hydrogen bonding is important for the hydrides of nitrogen, oxygen and fluorine, the smallest and most electronegative","options":["alkali metals","first-row non-metals","lanthanoids","noble gases"],"answer_index":1,"explanation":"Only N, O and F are small and electronegative enough for strong intermolecular hydrogen bonds.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-262","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lithium burns in air to give mainly the monoxide Li₂O, whereas sodium readily forms the","options":["hydride only","peroxide","ozonide exclusively","nitride vapour"],"answer_index":1,"explanation":"The small Li⁺ ion is stabilised by the small O²⁻ ion; larger Na⁺ prefers the peroxide O₂²⁻.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-263","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Carbon–carbon single bonds are much stronger than silicon–silicon bonds, so catenation is far more characteristic of","options":["silicon","carbon","lead","tin"],"answer_index":1,"explanation":"The short, strong C–C bond and the inability of C to use d orbitals make long carbon chains uniquely stable.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-264","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Boron forms electron-deficient compounds such as B₂H₆, a behaviour not typical of","options":["boron itself","aluminium alkyls in the same simple way","all p-block metals","helium"],"answer_index":1,"explanation":"Tiny boron has fewer valence orbitals than it needs for ordinary 2c–2e bonds, so it uses 3c–2e bridges.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-265","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine shows only the −1 oxidation state in its compounds, whereas chlorine can show","options":["only −1 as well","several positive oxidation states","the +8 state in ClF₈","no covalent compounds"],"answer_index":1,"explanation":"F is the most electronegative element and has no vacant d orbitals, so it never takes a positive OS.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-266","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lithium resembles magnesium more than sodium because Li⁺ and Mg²⁺ have similar charge-to-radius ratios, giving both a","options":["low polarising power","high polarising power","closed 3d¹⁰ shell","gaseous metallic lattice"],"answer_index":1,"explanation":"The two ions polarise anions strongly, so their oxides, fluorides and organometallic compounds look alike — the diagonal relationship.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-267","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Periodicity of properties arises because similar valence-shell configurations recur at regular intervals of","options":["atomic mass only","atomic number","neutron number","mass defect"],"answer_index":1,"explanation":"Each time a given ns / np pattern repeats, the chemistry of that group reappears.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-268","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Effective nuclear charge experienced by a valence electron is written $Z_{\\mathrm{eff}}=Z-\\sigma$, where $\\sigma$ is the","options":["atomic mass","screening constant","mass number","group number"],"answer_index":1,"explanation":"Inner electrons cancel part of Z; the remainder is the effective nuclear charge felt by the outer electron.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
    chapter_id text,
    subject_id text,
